package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.PhoneNumberVerifiedVO;

class PhoneNumberVerifiedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of phone number verified of user profile")
  void test_phone_number_verified_value_holder_assign_plain_value() {
    Object holder = new Object();
    PhoneNumberVerifiedValueHolder<Object> value = new PhoneNumberVerifiedValueHolder<>(holder);
    Assertions.assertSame(holder, value.phoneNumberVerified(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getPhoneNumberVerifiedValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getPhoneNumberVerified().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.phoneNumberVerifiedNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getPhoneNumberVerifiedValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of phone number verified of user profile")
  void test_phone_number_verified_value_holder_assign_value_object() {
    Object holder = new Object();
    PhoneNumberVerifiedValueHolder<Object> value = new PhoneNumberVerifiedValueHolder<>(holder);
    PhoneNumberVerifiedVO vo = PhoneNumberVerifiedVO.from(true);
    Assertions.assertFalse(value.getPhoneNumberVerifiedValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.phoneNumberVerified(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPhoneNumberVerifiedValue().orElseThrow());
    Assertions.assertSame(holder, value.phoneNumberVerified(Optional.empty()));
    Assertions.assertFalse(value.getPhoneNumberVerifiedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.phoneNumberVerified(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPhoneNumberVerifiedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of phone number verified of user profile against the original")
  void test_phone_number_verified_value_holder_read() {
    Object holder = new Object();
    PhoneNumberVerifiedValueHolder<Object> value = new PhoneNumberVerifiedValueHolder<>(holder);
    PhoneNumberVerifiedVO vo = PhoneNumberVerifiedVO.from(true);
    PhoneNumberVerifiedVO other = PhoneNumberVerifiedVO.from(true);
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getPhoneNumberVerifiedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPhoneNumberVerified(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPhoneNumberVerified(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.phoneNumberVerified(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPhoneNumberVerified(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPhoneNumberVerified(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of phone number verified of user profile")
  void test_phone_number_verified_value_holder_unset() {
    Object holder = new Object();
    PhoneNumberVerifiedValueHolder<Object> value = new PhoneNumberVerifiedValueHolder<>(holder);
    PhoneNumberVerifiedVO vo = PhoneNumberVerifiedVO.from(true);
    value.phoneNumberVerified(vo);
    Assertions.assertSame(holder,
        value.unsetPhoneNumberVerifiedIfMatches("phoneNumberVerified_other"));
    Assertions.assertTrue(value.getPhoneNumberVerifiedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPhoneNumberVerifiedIfMatches("phoneNumberVerified"));
    Assertions.assertFalse(value.getPhoneNumberVerifiedValue().isPresent(),
        "The field name must clear the value");
    value.phoneNumberVerified(vo);
    Assertions.assertSame(holder, value.unsetPhoneNumberVerified());
    Assertions.assertFalse(value.getPhoneNumberVerifiedValue().isPresent(),
        "Unset must clear the value");
  }
}
